"""Native rules stay reviewable; Kustomize projects them into a live Prometheus mount."""
import json
from pathlib import Path
PROM='prom/prometheus:v3.13.3'
BUSYBOX='busybox@sha256:dc2d74b28e4cf8984fa52af1f39bc7c3d9c73760b41a74d629f5d11b1ab28616'
def files(root,host_ip):
    labels={'app':'testlab-gitops-prometheus'}
    mounts=[{'name':'config','mountPath':'/etc/prometheus/config','readOnly':True},{'name':'rules','mountPath':'/etc/prometheus/rules','readOnly':True},{'name':'tls','mountPath':'/etc/prometheus/tls','readOnly':True}]
    deployment={'apiVersion':'apps/v1','kind':'Deployment','metadata':{'name':'testlab-prometheus'},'spec':{'replicas':1,'selector':{'matchLabels':labels},'template':{'metadata':{'labels':labels},'spec':{'shareProcessNamespace':True,'hostAliases':[{'ip':host_ip,'hostnames':['host.docker.internal']}],'securityContext':{'runAsUser':65534,'runAsGroup':65534,'fsGroup':65534},'containers':[{'name':'prometheus','image':PROM,'args':['--config.file=/etc/prometheus/config/prometheus.yml','--web.config.file=/etc/prometheus/config/web.yml','--storage.tsdb.path=/prometheus','--storage.tsdb.retention.time=2d'],'ports':[{'containerPort':9090}],'resources':{'requests':{'memory':'96Mi','cpu':'100m'},'limits':{'memory':'384Mi','cpu':'500m'}},'volumeMounts':mounts+[{'name':'data','mountPath':'/prometheus'}]},{'name':'reload','image':BUSYBOX,'command':['sh','-ec','old=""; while true; do current=$(sha256sum /etc/prometheus/rules/testlab-rules.yml); if [ "$current" != "$old" ]; then pid=$(pidof prometheus || true); if [ -n "$pid" ]; then kill -HUP "$pid"; old="$current"; fi; fi; sleep 5; done'],'resources':{'requests':{'memory':'8Mi','cpu':'10m'},'limits':{'memory':'32Mi','cpu':'100m'}},'volumeMounts':[mounts[1]]}],'volumes':[{'name':'config','configMap':{'name':'testlab-prometheus-config'}},{'name':'rules','configMap':{'name':'testlab-native-rules'}},{'name':'tls','secret':{'secretName':'testlab-prometheus-tls','defaultMode':292}},{'name':'data','emptyDir':{}}]}}}}
