    config={'apiVersion':'v1','kind':'ConfigMap','metadata':{'name':'testlab-prometheus-config'},'data':{'prometheus.yml':'global:\n  scrape_interval: 5s\n  evaluation_interval: 5s\nrule_files:\n  - /etc/prometheus/rules/testlab-rules.yml\nscrape_configs:\n  - job_name: testlab-gitops\n    static_configs:\n      - targets: [host.docker.internal:18578]\n','web.yml':'tls_server_config:\n  cert_file: /etc/prometheus/tls/tls.crt\n  key_file: /etc/prometheus/tls/tls.key\n'}}
